-- =========================================================
-- November forecast test data for occuvision
-- occupancy_logs + alerts from 2026-09-15 through 2026-11-30, hourly 08:00-15:00,
-- rooms 1-5 (camera_id = room_id), same per-room / per-weekday patterns as
-- seed_mock_data.sql (weekday means and spread were taken from it).
-- Run AFTER seed_mock_data.sql. Safe to re-run: it only deletes rows
-- inside 2026-09-15 .. 2026-11-30 before re-inserting them.
--
-- Built-in anomalies (to see where the forecast misses):
--   2026-11-16..2026-11-20  midterm week: Computer Lab A +25%, Lecture Hall 101 +15%
--   2026-11-24              low-attendance day: all rooms at ~10% of normal
-- =========================================================
USE occuvision;

DELETE FROM alerts         WHERE created_at >= '2026-09-15 00:00:00' AND created_at < '2026-12-01 00:00:00';
DELETE FROM occupancy_logs WHERE recorded_at >= '2026-09-15 00:00:00' AND recorded_at < '2026-12-01 00:00:00';

